-- 154 | 2026-11-21 | Round 2 P1: sparse old districts in Dong Thap, Kien Giang, Soc Trang.
-- 9 sourced research candidates across 3 old districts; NOT actual verified retail stores.
-- Old administrative province/district keys are deliberate, including the merged-provincial 2026 maps labels.
-- Source listing dates vary; opening status, stationery inventory, address and phones need Sales verification.
-- No visits/GPS/customer updates. Append-only, exact source-key and name/phone/tax duplicate guards.
WITH src AS (
  SELECT x.*, md5('fbmn:old13:round02:154:' || x.source_key) AS dg
  FROM jsonb_to_recordset('[{"province":"Đồng Tháp","district":"Huyện Tam Nông","name":"Nhà Sách Trần Hưng Đạo","address_line":"MH97+X6V, đường Trần Hưng Đạo, thị trấn Tràm Chim cũ, huyện Tam Nông, Đồng Tháp","category":"nha_sach","phone":"02773828979","tax_code":null,"source_key":"sotayvang:nhasach-tranhungdao:tramchim","source_url":"https://sotayvang.com/nha-sach-tran-hung-dao-tt-tram-chim/","verification_note":"Danh bạ Sổ Tay Vàng có tên, số điện thoại và plus code; chưa kiểm cửa hàng hoạt động 2026, không đồng nhất với Nhà sách Anh Tuấn cùng tuyến đường."},{"province":"Đồng Tháp","district":"Huyện Tam Nông","name":"Hiệu sách Minh Phụng","address_line":"MHC4+RF8, đường Trần Hưng Đạo, thị trấn Tràm Chim cũ, huyện Tam Nông, Đồng Tháp","category":"nha_sach","phone":"02773827641","tax_code":null,"source_key":"sotayvang:hieusach-minhphung:tramchim","source_url":"https://sotayvang.com/hieu-sach-minh-phung-tt-tram-chim/","verification_note":"Danh bạ địa phương ghi rõ hiệu sách và số điện thoại, chưa xác minh hiện còn bán sách/VPP."},{"province":"Đồng Tháp","district":"Huyện Tam Nông","name":"Văn phòng phẩm Khánh Vy","address_line":"Khu vực Tràm Chim, huyện Tam Nông cũ, Đồng Tháp (Maps chưa có số nhà)","category":"van_phong_pham","phone":"0837618715","tax_code":null,"source_key":"gmap:ChIJERo43pZaCjERADyqF4Y3HA8","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Kh%C3%A1nh%20Vy%20Huy%E1%BB%87n%20Tam%20N%C3%B4ng%20%C4%90%E1%BB%93ng%20Th%C3%A1p&query_place_id=ChIJERo43pZaCjERADyqF4Y3HA8","verification_note":"Bản đồ ghi Office supply store tại Tràm Chim và số điện thoại; địa chỉ thiếu số nhà, ưu tiên gọi xác nhận trước khi đến."},{"province":"Kiên Giang","district":"Huyện Giồng Riềng","name":"Văn phòng phẩm Thùy Dương","address_line":"W6FJ+869, đường Nguyễn Tấn Thiêm, xã Bàn Tân Định cũ, huyện Giồng Riềng, Kiên Giang","category":"van_phong_pham","phone":"0945811311","tax_code":null,"source_key":"gmap:ChIJl1yXUQC5oDERbTvEcl7lrqs","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Th%C3%B9y%20D%C6%B0%C6%A1ng%20Huy%E1%BB%87n%20Gi%E1%BB%93ng%20Ri%E1%BB%81ng%20Ki%C3%AAn%20Giang&query_place_id=ChIJl1yXUQC5oDERbTvEcl7lrqs","verification_note":"Google Maps ghi Stationery store, có danh bạ Sổ Tay Vàng trùng tên và số; chưa kiểm chứng hoạt động 2026."},{"province":"Kiên Giang","district":"Huyện Giồng Riềng","name":"Cơ sở in - photocopy - văn phòng phẩm Vũ Hiên","address_line":"W69Q+F46, xã Bàn Tân Định cũ, huyện Giồng Riềng, Kiên Giang","category":"van_phong_pham","phone":"0919827103","tax_code":null,"source_key":"sotayvang:vu-hien:ban-tan-dinh","source_url":"https://sotayvang.com/co-so-in-photocopy-van-phong-pham-vu-hien-ban-tan-dinh/","verification_note":"Nguồn danh bạ đặt cơ sở tại Bàn Tân Định, có số điện thoại nhưng phân loại ''trung tâm thương mại''; chưa khẳng định có quầy VPP hiện hoạt động."},{"province":"Sóc Trăng","district":"Huyện Mỹ Xuyên","name":"Cửa Hàng Văn Phòng Phẩm Trung Hưng","address_line":"17 Nguyễn Thái Học, thị trấn Mỹ Xuyên cũ, huyện Mỹ Xuyên, Sóc Trăng","category":"van_phong_pham","phone":"02993851058","tax_code":null,"source_key":"gmap:ChIJhbf4TnJNoDER1X7T96CCLyk","source_url":"https://www.google.com/maps/search/?api=1&query=C%E1%BB%ADa%20H%C3%A0ng%20V%C4%83n%20Ph%C3%B2ng%20Ph%E1%BA%A9m%20Trung%20H%C6%B0ng%20Huy%E1%BB%87n%20M%E1%BB%B9%20Xuy%C3%AAn%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJhbf4TnJNoDER1X7T96CCLyk","verification_note":"Google Maps và danh bạ ghi đúng tên/địa chỉ/điện thoại; bản đồ phân loại Novelty store, chưa kiểm chứng danh mục bán lẻ năm 2026."},{"province":"Sóc Trăng","district":"Huyện Mỹ Xuyên","name":"Cửa Hàng Văn Phòng Phẩm Thành Phát","address_line":"28 ĐT8, thị trấn Mỹ Xuyên cũ, huyện Mỹ Xuyên, Sóc Trăng","category":"van_phong_pham","phone":"02993851522","tax_code":null,"source_key":"gmap:ChIJc9E363JNoDERuVb0iSX9e3w","source_url":"https://www.google.com/maps/search/?api=1&query=C%E1%BB%ADa%20H%C3%A0ng%20V%C4%83n%20Ph%C3%B2ng%20Ph%E1%BA%A9m%20Th%C3%A0nh%20Ph%C3%A1t%20Huy%E1%BB%87n%20M%E1%BB%B9%20Xuy%C3%AAn%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJc9E363JNoDERuVb0iSX9e3w","verification_note":"Bản đồ ghi tên VPP Thành Phát và số điện thoại; chưa kiểm trực tiếp địa chỉ và mặt hàng."},{"province":"Sóc Trăng","district":"Huyện Mỹ Xuyên","name":"Cửa Hàng Tin Học - VPP - Photocopy NK","address_line":"8 Lê Lợi, thị trấn Mỹ Xuyên cũ, huyện Mỹ Xuyên, Sóc Trăng","category":"van_phong_pham","phone":"0909053539","tax_code":null,"source_key":"gmap:ChIJV19vqXpNoDER0nRLoryE3-k","source_url":"https://www.google.com/maps/search/?api=1&query=C%E1%BB%ADa%20H%C3%A0ng%20Tin%20H%E1%BB%8Dc%20-%20VPP%20-%20Photocopy%20NK%20Huy%E1%BB%87n%20M%E1%BB%B9%20Xuy%C3%AAn%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJV19vqXpNoDER0nRLoryE3-k","verification_note":"Bản đồ và danh bạ địa điểm in ấn nêu dịch vụ tin học và VPP; chưa có bằng chứng hiện bán học phẩm, cần Sales gọi và ghé xác minh."},{"province":"Sóc Trăng","district":"Huyện Mỹ Xuyên","name":"Cửa hàng văn phòng phẩm Trần Thúy Minh","address_line":"92 ấp Châu Thành, thị trấn Mỹ Xuyên cũ, huyện Mỹ Xuyên, Sóc Trăng","category":"van_phong_pham","phone":"0913515886","tax_code":null,"source_key":"sotayvang:tran-thuy-minh:myxuyen","source_url":"https://sotayvang.com/cua-hang-van-phong-pham-tran-thuy-minh-tt-my-xuyen/","verification_note":"Sổ Tay Vàng ghi tên, địa chỉ và số điện thoại nhưng danh mục đăng ký là ''Nhà sản xuất''; không coi đã xác minh quầy bán lẻ VPP."}]'::jsonb)
  AS x(province text,district text,name text,address_line text,category text,phone text,tax_code text,
       source_key text,source_url text,verification_note text)
), ins AS (
  INSERT INTO public.field_prospects (
    id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,
    note,status,source_kind,research_source_key,research_source_url,research_batch
  )
  SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
    NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
    s.name,s.address_line,s.province,s.district,s.category,s.phone,s.tax_code,
    'Vòng 2 P1 nghiên cứu nguồn công khai 21/11/2026; CHƯA GHÉ; chưa xác minh GPS hoặc cửa hàng đang kinh doanh. '
      ||s.verification_note||' Nguồn: '||s.source_url,
    'new','manual',s.source_key,s.source_url,'2026-11-21-old13-round02-p1-sparse-154'
  FROM src s
  WHERE (s.province,s.district) IN (
     ('Đồng Tháp','Huyện Tam Nông'),('Kiên Giang','Huyện Giồng Riềng'),('Sóc Trăng','Huyện Mỹ Xuyên'))
    AND s.source_url LIKE 'https://%'
    AND NOT EXISTS (SELECT 1 FROM public.customers c
      WHERE (c.province=s.province AND c.district=s.district AND lower(trim(c.name))=lower(trim(s.name)))
        OR (s.phone IS NOT NULL AND c.phone IS NOT NULL
          AND regexp_replace(c.phone,'[^0-9]','','g')=regexp_replace(s.phone,'[^0-9]','','g')))
    AND NOT EXISTS (SELECT 1 FROM public.field_prospects p
      WHERE p.research_source_key=s.source_key
        OR (p.province=s.province AND p.district=s.district AND lower(trim(p.name))=lower(trim(s.name)))
        OR (s.phone IS NOT NULL AND p.phone IS NOT NULL
          AND regexp_replace(p.phone,'[^0-9]','','g')=regexp_replace(s.phone,'[^0-9]','','g'))
        OR (s.tax_code IS NOT NULL AND p.tax_code=s.tax_code))
  ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
  RETURNING province,district,name,category
)
SELECT province,district,name,category FROM ins ORDER BY province,district,name;
